    }
    m = '接口正常（' + n + ' 分类）';
  } catch (e) { m = '接口异常：' + e; }
  lvToast(m);
}

function lvAbout() {
  lvToast('番茄小说TS\n'
    + '小说 / 听书 / 短剧，进章节自动播放\n'
    + '搜索前缀：+3小说 +2听书 +11短剧\n'
    + '＋书号(id) 直达详情');
}

function lvStatus() {
  var d = lvState();
  lvToast('模式：' + (d.mode || '小说')
    + '\n段评：' + (d.showPara !== false ? '开' : '关')
    + '｜听书播放：' + (d.audioPlay !== false ? '开' : '关')
    + '｜摘要：' + (d.summary ? '开' : '关'));
}

if (!source.getVariable()) lvBegin();

