// 当前书源版本号，切勿修改，否则影响更新的识别
let localVersion = '26.10.9';

// 初始服务器列表
let hosts = [
    'https://v1.qingtian618.com',
    'https://cdn.qingtian618.com',
    'https://v2.qingtian618.com',
    'https://v3.qingtian618.com',
    'https://v4.qingtian618.com',
    'https://v5.qingtian618.com',
    'https://v6.qingtian618.com',
    'https://v7.qingtian618.com'
];

function isSpecialMedia (sources) {
	let SOURCES_SPECIAL_MEDIA = ['毒舌影视', 'NT动漫'];
	 return SOURCES_SPECIAL_MEDIA.some(src => sources.includes(src));
	}

function buildDiscussionButton(url,sources)  {
    let clickAction =
        `showCmt("${url}","${sources}",'本书讨论')`;

    return `
        <button style="">💬 书籍讨论@onclick:${clickAction}</button>
    `;
};

// 初始化值
const defaultConfig = {
    线路: hosts[0],
    发现页来源: "番茄",
    发现页类型: "小说"
};

// 获取云端配置
function getCloudSettings(r) {
    if (r == undefined) r = false;
    const {
        java,
        cache
    } = this;
    let c = this.getVariable('云端配置').version;
    if (r || !c) {
        java.longToast(`\n正在更新最新配置`);
        try {
            let url = `/static/source_config/config.json`;
            //	java.longToast(url)
            let js = this.request(url);
            js = JSON.parse(String(js));
            let intc = parseInt(c);
            let intv = parseInt(js['version']);
            if (intc >= intv) {
            	    java.longToast(`\n已是最新配置：${js['version']}`);
            	    return;
            	} else if (!intc && intv) {
            		java.longToast(`\n已初始化配置：${intv}`);
            		} else if (intc < intv || !intc && intv) {
            java.longToast(`\n已更新配置：${intc}→${intv}`);
            } else {
            java.longToast(`\n获取配置失败：请切换线路再试试~`);
            return;
            }
            this.setVariable('云端配置', js);

            return js;
        } catch (e) {
            java.longToast(`\n获取最新配置失败：${e}`);
